SELECT id, order_no AS orderNo, user_id AS userId, order_type AS orderType, total_cent AS totalCent,
       status, seckill_activity_id AS seckillActivityId, created_at AS createdAt
FROM bc_trade_order_${shard}
WHERE id = #{orderId} AND user_id = #{userId}

SELECT id, order_no AS orderNo, user_id AS userId, order_type AS orderType, total_cent AS totalCent,
       status, seckill_activity_id AS seckillActivityId, created_at AS createdAt
FROM bc_trade_order_${shard}
WHERE user_id = #{userId}
ORDER BY id DESC
LIMIT #{limit}
